typedef struct {
    int *data;
    size_t size;
    size_t capacity;
} Vector;

void vector_push(Vector *v, int item) {
    if (v->size == v->capacity) {
        v->capacity = v->capacity == 0 ? 4 : v->capacity * 2;
        v->data = realloc(v->data, v->capacity * sizeof(int));
    }
    v->data[v->size++] = item;
}

typedef struct {
    char *buf;
    size_t head;
    size_t tail;
    size_t size;
    size_t capacity;
} RingBuffer;

int ring_push(RingBuffer *rb, char c) {
    if (rb->size == rb->capacity) return -1;
    rb->buf[rb->tail] = c;
    rb->tail = (rb->tail + 1) % rb->capacity;
    rb->size++;
    return 0;
}

int binary_search(const int *arr, int len, int target) {
    int low = 0, high = len - 1;
    while (low <= high) {
        int mid = low + (high - low) / 2;
        if (arr[mid] == target) return mid;
        if (arr[mid] < target) low = mid + 1;
        else high = mid - 1;
    }
    return -1;
}

